(() => {
'use strict';
const q=(id,prompt,options,correct,why)=>({id,prompt,options,correct,why});
const n=(id,prompt,answer,unit,why)=>({id,prompt,answer,unit,why});
const sources={grid:['Svenska kraftnät · Sveriges elnät','https://www.svk.se/om-kraftsystemet/oversikt-av-kraftsystemet/sveriges-elnat/'],balance:['Svenska kraftnät · BRP','https://www.svk.se/aktorsportalen/balansansvarig-part/'],roles:['Svenska kraftnät · Roller i kraftsystemet','https://www.svk.se/om-kraftsystemet/oversikt-av-kraftsystemet/roller-i-kraftsystemet/'],market:['Nord Pool · 15 minuters handel','https://www.nordpoolgroup.com/en/trading/transition-to-15-minute-market-time-unit-mtu/'],products:['Kraftringen · Portföljförvaltning','https://www.kraftringen.se/foretag/el/vara-elavtal/portfoljforvaltning/'],terms:['Kraftringen · Företagsvillkor','https://www.kraftringen.se/foretag/el/vara-elavtal/avtalsvillkor/']};
const modules=[
{id:'grid',title:'Från kraftverk till kund',category:'Gemensam grund',minutes:8,widget:'grid',sources:['grid'],sections:[
['Tre nätnivåer','Transmissionsnätet, även kallat stamnätet, transporterar stora mängder el över långa avstånd och förvaltas av Svenska kraftnät. Regionnäten för elen vidare och kan ansluta stora industrier. Lokalnäten når bland annat hushåll och mindre verksamheter. Produktion kan anslutas på olika nivåer: elen går inte alltid enbart uppifrån och ned.'],
['Två olika avtal','Elhandelsbolaget säljer elen enligt kundens elhandelsavtal. Nätföretaget ansvarar för nätanslutning och transport där anläggningen ligger. Ett byte av elhandlare flyttar inte anläggningen till ett annat nätföretag. Avbrott i nätet hanteras av nätföretaget, medan frågor om elhandelspris hör till elhandlaren.'],
['Effekt är inte energi','kW beskriver effekt. kWh beskriver energi: effekt × tid. Två maskiner på 10 kW som körs samtidigt i två timmar använder 40 kWh med en sammanlagd effekt på 20 kW. Körs de efter varandra i två timmar vardera används samma energi men högst 10 kW, om ingen annan last finns. Det kan påverka nätkostnaden beroende på tariff. 1 MWh är 1 000 kWh.']],questions:[
q('g1','Ett företag byter elhandlare. Nästa dag uppstår ett lokalt kabelavbrott. Vilka två slutsatser är riktiga?',['Den nya elhandlaren ansvarar automatiskt för kabelreparationen.','Nätföretaget på platsen ansvarar fortfarande för elnätet.','Kunden bör felanmäla nätavbrottet till nätföretaget.','Bytet tar bort behovet av ett nätavtal.'],[1,2],'Elhandel och fysisk nätanslutning är skilda uppgifter. Byte av leverantör ändrar inte nätägaren.'),
n('g2','Två maskiner på 15 kW körs i två timmar vardera, efter varandra. Ingen annan förbrukning finns. Hur stor är den totala energin?',60,'kWh','2 × 15 kW × 2 h = 60 kWh. Maximal samtidig effekt är däremot 15 kW.'),
q('g3','En fabrik ansluts direkt till regionnätet och har lokal solel. Vilket resonemang håller?',['All el måste först passera ett lokalnät.','Produktion och stora kunder kan anslutas på andra nivåer än lokalnätet; solöverskott kan matas ut.','Solel gör balans mellan tillförsel och uttag onödig.'],[1],'Nätbilden är förenklad. Anslutningsnivå och flödesriktning beror på anläggningen.')]
},
{id:'balance',title:'Balansansvar och systemansvar',category:'Gemensam grund',minutes:8,widget:'balance',sources:['roles','balance'],sections:[
['Planera och handla','Balansansvarig part, BRP, har ett ekonomiskt och planeringsmässigt ansvar för tillförsel och uttag i sina punkter per elområde. Prognoser används för planeringen. När en prognos ändras kan handeln behöva justeras. En elhandlare kan ha eget balansansvar eller anlita en annan BRP.'],
['Fysisk balans i realtid','Svenska kraftnät ansvarar för balanseringen av hela det svenska kraftsystemet i realtid. Leverantörer av balanstjänster, BSP, erbjuder kvalificerade resurser för stödtjänster. BRP och BSP är olika roller även om samma företag kan ha flera roller.'],
['Avvikelse är inte kundens spotpris','Om den faktiska förbrukningen avviker från den planerade volymen uppstår en obalans i detta förenklade exempel. Obalansen hanteras i balansavräkningen. Kostnaden är inte automatiskt samma som spotpriset, och kundens kostnader bestäms av kundens avtal. Övningen bortser från produktion, förluster och andra portföljdelar.']],questions:[
q('b1','En kyldag väntas höja förbrukningen efter att dagen före-handeln gjorts. Vad är rimligt?',['BRP uppdaterar prognosen och kan justera handeln.','Nord Pool måste reparera elnätet.','Svenska kraftnät hanterar systemets kvarvarande obalanser i realtid.','Kundens elhandelsavtal upphör automatiskt.'],[0,2],'Planeringen och handeln sker hos marknadsaktörerna. Svenska kraftnät ansvarar för systembalansen i realtid.'),
n('b2','En portfölj har köpt 80 MWh för perioden men kunderna använder 95 MWh. Ingen produktion eller annan handel finns. Hur stort är underskottet?',15,'MWh','95 − 80 = 15 MWh. Det är en volymavvikelse, inte ett färdigt kostnadsbelopp.'),
q('b3','En kollega säger att BRP och BSP är samma uppgift. Vilken förklaring är korrekt?',['BRP har ekonomiskt balansansvar; BSP levererar balanstjänster. Ett företag kan ha båda rollerna.','BSP bestämmer alltid kundens elhandelspris.','BRP ansvarar för alla fysiska kablar i området.'],[0],'Skilj på ekonomiskt balansansvar, stödtjänstleverans och nätansvar.')]
},
{id:'market',title:'Nord Pool, spotpris och elområden',category:'Gemensam grund',minutes:10,widget:'market',sources:['market','roles'],sections:[
['Från bud till pris','På dagen före-marknaden matchas köp- och säljbud för kommande dygn inom den gemensamma europeiska marknadskopplingen. Nord Pool är en elbörs, inte Sveriges nätägare eller den enda elbörsen som kan hantera svenska områden. Utbud, efterfrågan och tillgänglig överföring påverkar priset.'],
['SE1, SE2, SE3 och SE4','Sverige har fyra elområden. När överföringen begränsar handeln kan områden få olika spotpriser. Stor produktion i ett område innebär därför inte att alla områden får samma pris. Väder påverkar både produktion och efterfrågan, men en enskild väderuppgift räcker inte för en prisprognos.'],
['Kvartar och senare justeringar','Dagen före-marknaden använder 15-minutersperioder sedan leveransdagen 1 oktober 2025. Under ett normalt dygn finns 96 sådana perioder; dygn med tidsomställning skiljer sig. Intradaghandel används för justeringar närmare leverans. Finansiell prissäkring är ett annat verktyg och ersätter inte behovet av fysisk balans.']],questions:[
q('m1','SE1 har produktionsöverskott men en överföringsbegränsning hindrar all billig el från att nå SE4. Vilka påståenden är hållbara?',['SE4 måste få samma pris eftersom båda områdena är svenska.','Områdespriser kan skilja sig när överföringen begränsar handeln.','Mer lokal tillgänglig produktion i SE4 kan påverka prisbilden där.','Ett byte av elhandlare flyttar kunden från SE4 till SE1.'],[1,2],'Priset påverkas av möjligheterna att överföra el. Kundens geografiska anläggning avgör området.'),
n('m2','Hur många 15-minutersperioder finns under ett normalt dygn på 24 timmar?',96,'perioder','24 × 4 = 96. Tidsomställningsdygn är undantag.'),
q('m3','En producent får ett driftstopp efter dagen före-auktionen. Vilken beskrivning stämmer?',['Dagen före-priset räknas alltid om retroaktivt för alla kunder.','Intradaghandel kan justera positionen; kvarvarande obalanser hanteras genom balansering och avräkning.','En finansiell säkring garanterar att den fysiska anläggningen fortsätter producera.'],[1],'Dagen före-handel, intradaghandel och balansering fyller olika funktioner.')]
},
{id:'price',title:'Från spotpris till kundens kostnad',category:'Gemensam grund',minutes:10,widget:'price',sources:['products'],sections:[
['Kundens profil spelar roll','Ett ovägt medelpris säger inte vad en kund med kvartspris faktiskt betalar för energin. Kostnaden beräknas genom att varje periods förbrukning multipliceras med periodens pris. Summan delas med total förbrukning för att få kundens förbrukningsvägda medelpris. Månadsprisavtal kan ha en annan avtalsbestämd beräkning.'],
['Fler delar än spot','Elhandelsavtalet kan omfatta inköpskostnader, balans- och handelskostnader, ursprungsgarantier, försäljningspåslag och fast avgift. Vilka poster som ingår eller tillkommer avgörs av avtalet. Räkna inte samma kostnad två gånger. Elnätsavgifter, skatter och moms behöver hanteras separat enligt gällande förutsättningar.'],
['Ett förenklat räkneexempel','100 kWh à 50 öre och 300 kWh à 150 öre ger 500 kr. Medelpriset blir 125 öre/kWh, inte 100. Ett påslag på 5 öre/kWh ger 20 kr, och en fast avgift på 40 kr ger totalt 560 kr för de visade elhandelsposterna. Exemplet är exklusive moms, elnät och andra avtalskostnader; det är ingen offert.']],questions:[
n('p1','Kunden använder 100 kWh à 50 öre och 300 kWh à 150 öre. Vilket är det förbrukningsvägda spotpriset?',125,'öre/kWh','(100 × 50 + 300 × 150) / 400 = 125 öre/kWh.'),
n('p2','Samma kund har energikostnaden 500 kr, påslag 5 öre/kWh för 400 kWh och fast avgift 40 kr. Vad blir summan av just dessa poster?',560,'kr','500 + 400 × 0,05 + 40 = 560 kr. Elnät, moms och andra poster ingår inte i frågan.'),
q('p3','En offert anges som spot + påslag. Vad måste du reda ut innan du jämför med en annan offert?',['Vilka inköpskostnader som ingår och vilka som tillkommer.','Fast avgift och hur priset viktas mot förbrukningen.','Att båda offerterna automatiskt innehåller nätkostnad.','Om beloppen jämförs med samma moms- och kostnadsavgränsning.'],[0,1,3],'Jämför samma kostnadsposter, profil och skatteavgränsning. Spot plus påslag är inte alltid en komplett prisbeskrivning.')]
},
{id:'hedge',title:'Prissäkring, volym och kvarvarande risk',category:'Gemensam grund',minutes:10,widget:'hedge',sources:['products','terms'],sections:[
['Prisrisk flyttas, den försvinner inte','En prissäkring minskar exponeringen mot vissa framtida prisrörelser för en avtalad volym och period. Den kan ge ett bättre eller sämre utfall jämfört med osäkrat spotpris i efterhand. En säkring är inte ett löfte om lägsta pris.'],
['Planerad och faktisk säkringsgrad','Säkras 80 MWh av en planerad förbrukning på 100 MWh är målet 80 %. Blir faktisk förbrukning 125 MWh motsvarar samma säkring 64 %. Blir den 80 MWh motsvarar säkringen 100 %. Både periodens volym och förbrukningsmönstret påverkar passningen. 80 % används här som utbildningsantagande, inte som allmänt produktvillkor.'],
['En enkel jämförelse','Om 80 % i en förenklad modell prissätts till 70 öre/kWh och 20 % till 120 öre/kWh blir det viktade priset 80 öre/kWh före andra kostnader. Modellen illustrerar blandningen; verkliga portföljavtal kan avräknas finansiellt och behöver sin egen prisformel.']],questions:[
n('h1','80 MWh har säkrats. Faktisk förbrukning blir 125 MWh. Vilken faktisk säkringsgrad motsvarar det?',64,'%','80 / 125 × 100 = 64 %. Målandel och faktiskt utfall är olika saker.'),
n('h2','I den förenklade modellen kostar 80 % av energin 70 öre/kWh och 20 % kostar 120 öre/kWh. Vad blir viktat pris före övriga kostnader?',80,'öre/kWh','0,8 × 70 + 0,2 × 120 = 80 öre/kWh.'),
q('h3','Spotpriset faller efter att kunden prissäkrat. Vad kan du säga?',['Prissäkring innebär alltid lägre pris än spot.','Säkringen kan ge högre kostnad än osäkrat spot i efterhand.','Kundens val ska bedömas mot risk- och budgetbehov, inte bara efterhandspriset.','Säkringen garanterar oförändrad förbrukning.'],[1,2],'Prissäkring hanterar risk och kan ge både positivt och negativt utfall relativt spot.')]
},
{id:'individual',title:'Individuell portfölj',category:'Företagsprodukter',minutes:9,widget:'hedge',sources:['products','terms'],sections:[
['Kundens egen profil','Enligt ert produktunderlag görs mindre säkringar löpande och profilen anpassas till den enskilda kundens behov. En säsongsberoende verksamhet behöver en annan fördelning än en jämnt förbrukande verksamhet. Bättre profilpassning minskar risken att den faktiska säkringsgraden avviker från målet, men tar inte bort prognosrisken.'],
['Behovsanalysen','Samla historisk förbrukning per relevant tidsperiod, framtida förändringar, anläggningar, budgetmål och riskvilja. En ny produktionslinje, solceller eller stängning kan ändra behovet. Årsvolymen ensam räcker inte för att förstå profilpassningen.'],
['Villkor att stämma av','Kraftringens publika portföljbeskrivning anger successiva säkringar och anpassade månadsvolymer. Exakt tidsupplösning, mandat, säkringsmål, kostnader och hantering av volymavvikelser ska följa kundens aktuella avtal. Utbildningen anger inga nya bindande affärsvillkor.']],questions:[
q('i1','Två företag använder båda 1 GWh per år. Ett använder mest på vintern, det andra på sommaren. Vad behöver utredas?',['Samma årsvolym innebär att samma säkringsprofil alltid passar.','Fördelningen över året och planerade verksamhetsförändringar.','Hur respektive profil matchas mot säkrad volym i leveransperioderna.'],[1,2],'Samma årsenergi kan dölja helt olika profiler och därmed olika faktisk säkringsgrad.'),
n('i2','En månad har kunden säkrat 60 MWh och använder 75 MWh. Vilken andel motsvarar säkringen?',80,'%','60 / 75 × 100 = 80 % för just denna månad.'),
q('i3','Kunden ska dubbla produktionen mitt under avtalsåret. Vad är ett välgrundat säljaragerande?',['Lova att befintlig säkring automatiskt omfattar hela ökningen.','Ta in en uppdaterad profil och stäm av ändringen mot förvaltning och avtalsvillkor.','Behålla samma årsprognos eftersom avtalet redan är skrivet.'],[1],'En individuell profil behöver hållas relevant när verksamheten förändras.')]
},
{id:'pool',title:'Poolportfölj',category:'Företagsprodukter',minutes:9,widget:'hedge',sources:['terms'],sections:[
['En gemensam inköpsstrategi','I ert underlag samlas kundernas behov i en pool med gemensam profil och löpande säkringar. Kunden får inte automatiskt en individuell inköpsprofil. Poolens strategi kan vara praktisk för kunder som vill överlåta inköpsarbetet, men profilavvikelser måste förklaras.'],
['Målet är inte en månadsgaranti','Om schablonen innebär 80 MWh säkrat och kunden faktiskt använder 110 MWh blir den illustrativa faktiska andelen cirka 73 %. Om användningen sjunker kan andelen bli högre. Bildens 80 % är ett mål för profilen, inte en garanti för varje kund varje månad.'],
['Trygg och Offensiv','Portalen har varianterna Trygg och Offensiv. Den här modulen förklarar den gemensamma poolprincipen. Variantens mandat, risknivå, avgifter, volymkrav och avräkning måste kontrolleras i aktuellt produktunderlag innan ett kundlöfte ges. Ett godkänt utbildningsmoment ersätter inte den kontrollen.']],questions:[
q('o1','En kund med tydlig vintertopp överväger en gemensam poolprofil. Vad behöver förklaras?',['Poolens profil behöver inte följa kundens individuella uttag.','En målandel på 80 % garanterar 80 % varje månad.','Kundens faktiska säkringsgrad kan avvika när uttaget avviker från schablonen.'],[0,2],'En kollektiv strategi innebär inte individuell profilpassning eller garanterad månadsandel.'),
n('o2','80 MWh är säkrat enligt övningens schablon. Kunden använder 100 MWh. Nästa period är samma volym säkrad men kunden använder 80 MWh. Vilken är andelen i den andra perioden?',100,'%','80 / 80 = 100 %. En lägre faktisk förbrukning höjer andelen för en given säkrad volym.'),
q('o3','En kund frågar vad som skiljer Trygg från Offensiv i det erbjudna avtalet. Vad är rätt nästa steg?',['Använda samma villkorsbeskrivning eftersom de ingår i en pool.','Kontrollera variantens förvaltningsmandat, risk och kostnader i aktuellt produktunderlag.','Lova att Offensiv alltid blir billigast.'],[1],'Poolprincipen är gemensam men detaljerna i respektive erbjudande måste verifieras.')]
},
{id:'direct',title:'Kraftringen Direkt',category:'Företagsprodukter',minutes:8,widget:'direct',sources:['terms'],sections:[
['Ett beslut, flera leveransperioder','Enligt ert produktunderlag säkras en större volym vid ett tillfälle för flera framtida leveransperioder. Beslutstidpunkten är gemensam, men periodernas terminspriser kan skilja sig. Det innebär inte automatiskt samma värde varje månad.'],
['När kan det passa?','Kunden vill fatta ett samlat beslut i ett visst marknadsläge och accepterar att periodernas säkringsvärden varierar. Ett koncentrerat säkringstillfälle innebär ett större beroende av just den tidpunktens marknadsläge än successiva inköp. Det är inget löfte om bättre utfall.'],
['Så förklarar säljaren','Visa leveransperioder och volymer separat från affärsdagen. Kontrollera vad som är säkrat, hur osäkrad volym hanteras och hur det finansiella utfallet påverkar kundens faktura. Exakt formel och villkor för Direkt behöver hämtas från det aktuella erbjudandet.']],questions:[
q('d1','Januari och februari säkras samma dag, men till olika terminspriser. Är olika värden per månad förenligt med Direkt enligt underlaget?',['Ja. Samma beslutstidpunkt betyder inte samma pris för varje leveransperiod.','Nej. Samma affärsdag måste ge samma månadspris.','Nej. Kunden kan inte säkra flera månader samma dag.'],[0],'Tidpunkt för affären och tidpunkt för leveransen är två olika dimensioner.'),
q('d2','Vad ska jämföras när kunden väljer mellan löpande säkring och ett större engångsbeslut?',['Kundens riskvilja och tolerans för valet av säkringstidpunkt.','Att engångsbeslut alltid ger lägsta möjliga pris.','Leveransperioder, volymer och kvarvarande exponering.'],[0,2],'Jämför både inköpsstrategi och det som faktiskt omfattas. Utfallet kan inte garanteras i förväg.'),
n('d3','I ett illustrativt exempel säkras 20 MWh för januari och 30 MWh för februari vid samma beslut. Hur stor total volym omfattar beslutet?',50,'MWh','20 + 30 = 50 MWh. Det säger inte att pris eller värde per månad är lika.')]
},
{id:'stable',title:'Kraftringen Stabil',category:'Företagsprodukter',minutes:8,widget:'stable',sources:['terms'],sections:[
['Utjämnad fördelning','Enligt ert underlag bygger Stabil på samma grundsäkring som Direkt, men säkringsvärdet fördelas jämnt över leveransperioden. Det är fördelningen av säkringsvärdet som jämnas ut. Det ska inte beskrivas som en automatisk garanti för samma totalfaktura varje månad.'],
['Samma värde kan uttryckas på olika sätt','Innan ett kundspecifikt räkneexempel används måste produktunderlaget klargöra om utjämningen avser kronor per månad, öre per kWh eller en annan avtalad fördelning. Övningen nedan visar endast en antagen fördelning i kronor. Den fastställer inte Kraftringens prisformel.'],
['Budget och återstående variation','Förbrukning, osäkrad exponering, andra elhandelskostnader och nätkostnader kan fortfarande variera. Förklara vilka delar som jämnas ut och vilka delar som inte gör det. Kunden kan värdera ett jämnare utfall utan att hela elkostnaden är fast.']],questions:[
q('s1','En kund tolkar Stabil som samma belopp på varje faktura. Vilka förtydliganden behövs?',['Utjämningen gäller säkringsvärdet enligt produktens avtalade modell.','Förbrukning och andra kostnadsdelar kan fortfarande påverka fakturan.','All förbrukning och alla nätavgifter är automatiskt fasta.'],[0,1],'Säkringsvärde är bara en del av kundens kostnad. Enheten och avräkningsmodellen måste klargöras.'),
n('s2','Endast i denna övning fördelas ett säkringsvärde på 12 000 kr jämnt över tre månader. Vad blir det per månad?',4000,'kr','12 000 / 3 = 4 000 kr. Detta är en illustrativ kronfördelning, inte produktens fastställda fakturaformel.'),
q('s3','Vad behöver du fastställa innan du säger att Stabil ger ett visst örepris?',['Om utjämningen avser kronor, öre/kWh eller annan fördelning samt kundens prisformel.','Enbart att det finns tolv månader i året.','Ingenting, eftersom ett jämnt värde alltid är ett fast örepris.'],[0],'Belopp och pris per energienhet är olika storheter; enheten får inte antas.')]
},
{id:'advice',title:'Kundfall: välj och förklara',category:'Tillämpning',minutes:10,widget:'price',sources:['products','terms'],sections:[
['Utgå från behovet','Börja med förbrukningens storlek och profil, framtida förändringar, budgetkrav och riskvilja. Jämför först därefter inköpsstrategier. Produkternas namn är inte i sig ett underlag för att rekommendera dem.'],
['Tre olika kundbehov','En säsongsindustri kan behöva individuell profilpassning. Ett företag som accepterar en kollektiv strategi kan undersöka poolalternativ. En kund som vill fatta ett större samlat säkringsbeslut kan undersöka Direkt eller Stabil, men behöver förstå skillnaden i hur säkringsvärdet fördelas. Lämplighet avgörs tillsammans med fullständiga villkor.'],
['Ett korrekt kundlöfte','Beskriv både vad produkten gör och vad som fortfarande kan variera. Räkneexempel är antaganden, inte prisprognoser. Produktutbildning ger inte rätt att lova lägsta pris, fast faktura eller andra villkor som saknas i erbjudandet.']],questions:[
q('a1','En kund använder 1 GWh per år, har stora säsongsvariationer och planerar en expansion. Vad behövs innan produktvalet?',['Periodiserad förbrukning och en uppdaterad prognos.','Kundens budgetmål och riskvilja.','En garanti om lägsta pris för att förenkla beslutet.'],[0,1],'Årsvolym räcker inte. Profil, förändringar och riskbehov behövs för en relevant jämförelse.'),
q('a2','Kunden vill säkra vid ett tillfälle och säger att lika fakturor är viktigast. Vad är det korrekta svaret?',['Stabil garanterar samma totalfaktura enligt utbildningsbilden.','Utred Stabil men förklara exakt vad som utjämnas och att totalfakturan kan variera.','Direkt och Stabil har identisk fördelning per månad.'],[1],'Bekräfta kundbehovet men skilj utjämnat säkringsvärde från garanterad totalfaktura.'),
q('a3','En annan offert har lägre påslag. Vilka kontroller behövs före en slutsats om lägre totalkostnad?',['Samma förbrukningsprofil och period.','Samma inkluderade avgifter, inköpskostnader och fast avgift.','Att lägre påslag alltid betyder lägre slutpris.','Samma risk och omfattning på prissäkringen.'],[0,1,3],'Prisjämförelsen behöver samma beräkningsgrund och riskomfattning.')]
}];
modules.forEach((m,i)=>{m.version=1;m.prerequisites=i<5?(i?[modules[i-1].id]:[]):i<9?['hedge']:['individual','pool','direct','stable'];});
window.PartnerLearningContent={revision:'2026-11-10.1',sources,modules};
})();
